mapper.select:
SELECT d.pkg_no, d.pk_seq, d.status AS pack_status, d.sizerun, d.ctn_pairs, d.nw, d.gw, d.item_no, d.s_no, d.e_no, d.length, d.width, d.high, b.ctns_number, b.barcode_no FROM se_pack_m d LEFT JOIN se_pack_barcode b ON b.org_id = d.org_id AND b.pkg_no = d.pkg_no AND b.ctns_number BETWEEN d.s_no AND d.e_no WHERE d.org_id = #{orgId} AND d.pkg_no IN
#{pkgNo}
ORDER BY d.pkg_no, d.pk_seq, b.ctns_number
